CREATE TABLE IF NOT EXISTS invoice_periods_v2(id TEXT PRIMARY KEY,contract_id TEXT NOT NULL,period_no INTEGER NOT NULL,status TEXT NOT NULL,current_gross TEXT NOT NULL,previous_gross TEXT NOT NULL,cumulative_gross TEXT NOT NULL,deduction TEXT NOT NULL,retention TEXT NOT NULL,adjustment TEXT NOT NULL,net_payable TEXT NOT NULL,snapshot_json TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,approved_by TEXT,approved_at TEXT,row_version INTEGER NOT NULL DEFAULT 1,UNIQUE(contract_id,period_no));
CREATE TABLE IF NOT EXISTS invoice_lines_v2(id TEXT PRIMARY KEY,period_id TEXT NOT NULL,contract_item_id TEXT NOT NULL,current_quantity TEXT NOT NULL,current_amount TEXT NOT NULL,previous_quantity TEXT NOT NULL,previous_amount TEXT NOT NULL,cumulative_quantity TEXT NOT NULL,cumulative_amount TEXT NOT NULL,sort_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settlements_v2(id TEXT PRIMARY KEY,contract_id TEXT NOT NULL UNIQUE,status TEXT NOT NULL,contract_amount TEXT NOT NULL,invoiced_amount TEXT NOT NULL,final_adjustment TEXT NOT NULL,final_amount TEXT NOT NULL,snapshot_json TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,approved_by TEXT,approved_at TEXT,row_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS acceptances_v2(id TEXT PRIMARY KEY,contract_id TEXT NOT NULL UNIQUE,settlement_id TEXT NOT NULL,status TEXT NOT NULL,inspection_date TEXT,result TEXT,defects_json TEXT NOT NULL,improvements_json TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,completed_by TEXT,completed_at TEXT,row_version INTEGER NOT NULL DEFAULT 1);
